    win = [False] * (N + 1)
    # win[n] is True if the player whose turn it is to move from n wins.
    # The player who writes N wins.
    # So if n is such that n+1=N or 2n=N, then the player moving from n wins.
    # Otherwise, the player moving from n wins if they can move to n' such that win[n'] is False.
    for n in range(N - 1, 0, -1):
