def is_type_b(N):
    if N == 1: return False
    win = [False] * (N + 1)
    for n in range(N - 1, 0, -1):
        if n + 1 == N or 2 * n == N:
            win[n] = True
        else:
            win[n] = (n + 1 < N and not win[n + 1]) or (2 * n < N and not win[2 * n])
    return win[1]

print(f"Is 400 type B? {is_type_b(400)}")
print(f"Is 512 type B? {is_type_b(512)}")

def solve_game_with_trace(N):
    win = [0] * (N + 1)
    for i in range(N - 1, 0, -1):
        if i + 1 == N or 2 * i == N:
            win[i] = 1
        else:
            can_move_to_loss = False
            if i + 1 < N and win[i + 1] == 0:
                can_move_to_loss = True
            if 2 * i < N and win[2 * i] == 0:
                can_move_to_loss = True
            win[i] = 1 if can_move_to_loss else 0
    return win

